```json
{
  "root_causes": [
    {
      "service": "ts-admin-user-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT duration/1e8 AS bucket_100ms_units, count(*) AS n, min(duration)/1e6 AS min_ms, max(duration)/1e6 AS max_ms FROM abnormal_traces WHERE service_name='ts-admin-user-service' AND attr_span_kind='Client' AND span_name='POST' GROUP BY 1 ORDER BY 1",
          "claim": "Admin-user POST calls to user-service cluster near ~300, ~700, ~1500, ~6900 ms, i.e. TCP retransmission-timeout multiples, absent in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.duration/1e6 client_ms, s.duration/1e6 server_ms, (c.duration - s.duration)/1e6 gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id = c.span_id AND s.service_name='ts-user-service' AND s.attr_span_kind='Server' WHERE c.service_name='ts-admin-user-service' AND c.attr_span_kind='Client' AND c.span_name='POST' ORDER BY client_ms DESC",
          "claim": "Slow admin-user→user-service POSTs have their own time near 1 ms; the extra time is in the wire/handoff between the two services."
        },
        {
          "kind": "trace",
          "sql": "SELECT u.span_name, u.duration/1e6 ui_ms, a.duration/1e6 admin_srv_ms FROM abnormal_traces u JOIN abnormal_traces a ON a.parent_span_id = u.span_id AND a.service_name='ts-admin-user-service' WHERE u.service_name='ts-ui-dashboard' AND u.span_name LIKE 'POST /api/v1/adminuserservice%' ORDER BY ui_ms DESC",
          "claim": "User-facing POST /api/v1/adminuserservice/users calls from ui-dashboard take 300–6900 ms, matching the admin-user server spans."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, quantile_cont(duration,0.95)/1e6 p95_ms, count(*) n FROM normal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/adminuserservice/users' GROUP BY 1,2 UNION ALL SELECT service_name, span_name, quantile_cont(duration,0.95)/1e6, count(*) FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/adminuserservice/users' GROUP BY 1,2",
          "claim": "ui-dashboard POST adminuserservice/users p95 rose from about 90 ms in normal to about 720 ms in abnormal."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-admin-user-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT u.span_name, u.duration/1e6 ui_ms, a.duration/1e6 admin_srv_ms FROM abnormal_traces u JOIN abnormal_traces a ON a.parent_span_id = u.span_id AND a.service_name='ts-admin-user-service' WHERE u.service_name='ts-ui-dashboard' AND u.span_name LIKE 'POST /api/v1/adminuserservice%' ORDER BY ui_ms DESC",
          "claim": "Each slow ui-dashboard admin-user POST contains a slow ts-admin-user-service server span of nearly identical duration."
        }
      ]
    }
  ]
}
```

